const rec = $('Idempotency Check').first().json || {};
const fields = rec.fields || rec;
return [{ json: {
  outcome: 'duplicate',
  correlation_id: fields.correlation_id || '',
  idempotency_key: fields.idempotency_key || '',
  message_id: fields.message_id || '',
  processing_status: fields.processing_status || 'received',
  draft_id: fields.draft_id || '',
  task_id: fields.task_id || '',
  message: 'Message already processed; no duplicate draft, task, or alert created.'
}}];

const j = $('On Canonical Email').item.json;
const config = {
  vip_domains: [],
  vip_senders: [],
  newsletter_senders: [],
  newsletter_subject_patterns: ['unsubscribe', 'weekly digest', 'newsletter', 'special offer'],
  blocked_senders: []
};
const email = String(j.from_email || '').toLowerCase();
const subject = String(j.subject || '').toLowerCase();
const domain = email.split('@')[1] || '';
const validationErrors = [];
if (!j.message_id) validationErrors.push('missing_message_id');
if (!email || !email.includes('@')) validationErrors.push('missing_or_invalid_sender');
let vip = false;
let newsletter = false;
let blocked = false;
let rule = 'proceed';
if (config.blocked_senders.includes(email)) {
  blocked = true;
  rule = 'blocked';
} else if (validationErrors.length) {
  rule = 'invalid_input';
} else {
  vip = config.vip_senders.includes(email) || config.vip_domains.includes(domain);
  newsletter =
    config.newsletter_senders.includes(email) ||
    config.newsletter_subject_patterns.some((pattern) => subject.includes(pattern));
  if (newsletter) rule = 'newsletter';
  else if (vip) rule = 'vip';
}
return [{ json: {
  ...j,
  rules: { vip, newsletter, blocked, rule },
  validation_errors: validationErrors,
  rejection_status: blocked ? 'blocked' : (validationErrors.length ? 'invalid_input' : ''),
  rejection_error_code: blocked ? 'blocked_sender' : (validationErrors[0] || ''),
  proceed: !blocked && validationErrors.length === 0
} }];

const email = $('Prepare Triage Input').item.json;
const triage = $input.first().json || {};
return [{ json: {
  ...email,
  triage: {
    review_required: !!triage.review_required,
    gate_reason: triage.gate_reason || '',
    category: triage.category || '',
    importance: triage.importance || '',
    needs_reply: !!triage.needs_reply,
    needs_task: !!triage.needs_task,
    summary: triage.summary || '',
    draft_reply: triage.draft_reply || '',
    suggested_due_at: triage.suggested_due_at || null,
    confidence: triage.confidence,
    sensitive: !!triage.sensitive,
    safety_reason: triage.safety_reason || null,
    review_queue_id: triage.review_queue_id || ''
  }
}}];

const j = $('Deterministic Rules').item.json;
const rec = $('Write Blocked Event').first().json || {};
return [{ json: {
  correlation_id: j.correlation_id,
  idempotency_key: j.idempotency_key,
  message_id: j.message_id,
  email_event_id: rec.id || '',
  outcome: j.rejection_status,
  error_code: j.rejection_error_code,
  validation_errors: j.validation_errors,
  final_status: 'rejected_before_ai_or_external_actions'
}}];
